#include <stdlib.h>
typedef struct { int *data; size_t n; } queue_t;
queue_t *queue_create(size_t n){
  queue_t *o=(queue_t*)malloc(sizeof(*o)); if(!o) return NULL;
  o->data=(int*)calloc(n,sizeof(int)); if(!o->data){free(o); return NULL;}
  o->n=n; return o;
}
void queue_destroy(queue_t **po){
  if(!po||!*po) return; free((*po)->data); free(*po); *po=NULL;
}
