#include <stdlib.h>
#include <string.h>
char *dup_slab(const char *s){
  if(!s) return NULL; size_t n=strlen(s);
  char *b=(char*)malloc(n+1); if(!b) return NULL;
  memcpy(b,s,n); b[n]='\0'; return b;
}
