```python
from typing import Hashable, Sequence, TypeVar
T = TypeVar('T', bound=Hashable)

def reduce_tree_items(xs: Sequence[T]) -> list[T]:
    seen: set[T] = set()
    out: list[T] = []
    for x in xs:
        if x not in seen:
            seen.add(x); out.append(x)
    return sorted(out)
```

