#include <stdlib.h>
typedef struct { int *data; size_t n; } arena_t;
arena_t *arena_create(size_t n){
  arena_t *o=(arena_t*)malloc(sizeof(*o)); if(!o) return NULL;
  o->data=(int*)calloc(n,sizeof(int)); if(!o->data){free(o); return NULL;}
  o->n=n; return o;
}
void arena_destroy(arena_t **po){
  if(!po||!*po) return; free((*po)->data); free(*po); *po=NULL;
}
