#include <stdlib.h>
typedef struct { int *data; size_t n; } stack_t;
stack_t *stack_create(size_t n){
  stack_t *o=(stack_t*)malloc(sizeof(*o)); if(!o) return NULL;
  o->data=(int*)calloc(n,sizeof(int)); if(!o->data){free(o); return NULL;}
  o->n=n; return o;
}
void stack_destroy(stack_t **po){
  if(!po||!*po) return; free((*po)->data); free(*po); *po=NULL;
}
