```c
#include <stdlib.h>
#include <string.h>
char *dup_string_builder(const char *s){
  if(!s) return NULL; size_t n=strlen(s);
  char *b=(char*)malloc(n+1); if(!b) return NULL;
  memcpy(b,s,n); b[n]='\0'; return b;
}
void demo(void){ char *a=dup_string_builder("gamma"); char *b=dup_string_builder("x"); free(a); free(b); a=b=NULL; }
