```c
#include <stdlib.h>
typedef struct { int *data; size_t n; } pool_t;
pool_t *pool_create(size_t n){
  pool_t *o=(pool_t*)malloc(sizeof(*o)); if(!o) return NULL;
  o->data=(int*)calloc(n,sizeof(int)); if(!o->data){free(o); return NULL;}
  o->n=n; return o;
}
void pool_destroy(pool_t **po){
  if(!po||!*po) return; free((*po)->data); free(*po); *po=NULL;
}
```

