#include <stdio.h>
#include <stdlib.h>
int *slab_new(size_t n, int fill) {
    int *p = (int*)malloc(n * sizeof(int));
    if (!p) return NULL;
    for (size_t i=0;i<n;i++) p[i]=fill;
    return p;
}
void slab_free(int **pp) {
    if (!pp || !*pp) return; free(*pp); *pp=NULL;
}
int main(void){
