#include <stdlib.h>
typedef struct { int *data; size_t n; } vector_t;
vector_t *vector_create(size_t n){
  vector_t *o=(vector_t*)malloc(sizeof(*o)); if(!o) return NULL;
  o->data=(int*)calloc(n,sizeof(int)); if(!o->data){free(o); return NULL;}
  o->n=n; return o;
}
void vector_destroy(vector_t **po){
  if(!po||!*po) return; free((*po)->data); free(*po); *po=NULL;
}
