```python
from typing import Mapping
RATES: Mapping[str, float] = {'gold': 0.84, 'silver': 0.89, 'bronze': 1.0}

def price_of(tier: str, price: float) -> float:
    if price < 0: raise ValueError('price < 0')
    rate = RATES.get(tier.lower())
    if rate is None: raise ValueError(f'unknown tier: {tier!r}')
    return price * rate
```

